#define _XOPEN_SOURCE 700

#include <stdlib.h>
#include <string.h>

#include "format.h"
#include "msg.h"
#include "path.h"
#include "tui.h"
#include "util.h"

#define MIN_COLS 40
#define MIN_ROWS 10
#define MAX_COLUMN 30		/* a fixed column wider than this is cut */
#define NONE ((size_t)-1)

/* Screen rows outside the panels: title, header, border, buttons, status. */
#define CHROME_ROWS 5

/* Lines of the details panel above the session table. */
#define DETAIL_HEAD 4

static const struct attr plain = { COLOR_DEFAULT, COLOR_DEFAULT, 0 };

static const char *const option_labels[OPTION_COUNT] = {
	"tui.option.theme"
};

static const char *const theme_names[THEME_COUNT] = {
	"tui.theme.auto", "tui.theme.system", "tui.theme.light", "tui.theme.dark"
};

static const char *const list_headers[TUI_COLUMNS] = {
	"list.col.state", "list.col.project", "list.col.sessions",
	"list.col.size", "list.col.modified"
};

static const char *const trash_headers[TRASH_COLUMNS] = {
	"trash.col.entry", "trash.col.removed", "list.col.size",
	"list.col.project"
};

/* Columns that give up their room first when the flexible one is narrow. */
static const size_t list_drop[] = { SORT_MODIFIED, SORT_SIZE, SORT_SESSIONS };
static const size_t session_drop[] = { 3, 0, 2, 4 };
static const size_t trash_drop[] = { 2, 1 };

/* The title of the lower panel while a change is prepared, per action. */
static const char *const plan_titles[] = {
	"", "tui.plan.move", "tui.plan.fix", "tui.plan.remove",
	"tui.plan.prune", "tui.plan.restore", "tui.plan.delete"
};

static const char *const questions[] = {
	"", "", "", "tui.ask.remove", "tui.ask.prune", "", "tui.ask.delete"
};

/* Line drawing and arrows need UTF-8; other locales get ASCII. */
static const char *glyph(const char *utf8, const char *ascii)
{
	return MB_CUR_MAX > 1 ? utf8 : ascii;
}

static struct attr style(unsigned long fg, unsigned char st)
{
	struct attr a;

	a.fg = fg;
	a.bg = COLOR_DEFAULT;
	a.style = st;
	return a;
}

/*
 * Orphaned and unavailable look the same wherever they appear. Without
 * colour the word itself carries the meaning, the style only helps.
 */
static const struct theme_colors *palette(const struct tui *t)
{
	return tui_theme(t);
}

static struct attr state_attr(const struct tui *t, const struct screen *s,
    enum dir_state state, unsigned char base)
{
	if (state == STATE_ORPHAN)
		return style(palette(t)->red, base | STYLE_BOLD);
	if (state == STATE_UNAVAILABLE)
		return style(palette(t)->yellow, base | (s->color ?
		    palette(t)->yellow_style : STYLE_UNDERLINE));
	return style(COLOR_DEFAULT, base);
}

static struct attr grey(const struct tui *t, const struct screen *s)
{
	return style(palette(t)->grey, s->color ? 0 : STYLE_DIM);
}

static struct attr error_attr(const struct tui *t)
{
	return style(palette(t)->red, STYLE_BOLD);
}

static struct attr warning_attr(const struct tui *t, const struct screen *s)
{
	return style(palette(t)->yellow, s->color ? palette(t)->yellow_style :
	    STYLE_BOLD);
}

/* The chosen row, the same everywhere: blue, reversed without colour. */
static struct attr chosen(const struct tui *t, const struct screen *s)
{
	struct attr a = plain;

	if (s->color)
		a.bg = palette(t)->select;
	else
		a.style = STYLE_REVERSE;
	return a;
}

/* A bar (title, buttons): grey, plain without colour. */
static struct attr bar_attr(const struct tui *t)
{
	struct attr a = plain;

	a.bg = palette(t)->bar;
	return a;
}

/* Keeps pos visible in rows lines starting at *top. */
static void scroll_to(size_t *top, size_t pos, size_t rows)
{
	if (rows == 0)
		return;
	if (pos < *top)
		*top = pos;
	else if (pos >= *top + rows)
		*top = pos - rows + 1;
}

/* A first row that leaves no empty rows below the last item. */
static void clamp_top(size_t *top, size_t count, size_t rows)
{
	size_t last = count > rows ? count - rows : 0;

	if (*top > last)
		*top = last;
}

/*
 * One table row from x0: cells by widths (0: column left out), TUI_GAP
 * between. first, when given, is the attribute of the first column.
 */
static void draw_row(struct screen *s, size_t x0, size_t y, char *const *cells,
    const size_t *widths, size_t n, unsigned right, struct attr attr,
    const struct attr *first)
{
	size_t x = x0, c;
	int any = 0;

	screen_text(s, 0, y, s->cols, "", attr, 0);
	for (c = 0; c < n; c++) {
		if (widths[c] == 0)
			continue;
		if (any)
			x += TUI_GAP;
		if (x >= s->cols)
			break;
		screen_text(s, x, y, widths[c], cells[c],
		    c == 0 && first != NULL ? *first : attr, (right >> c) & 1);
		x += widths[c];
		any = 1;
	}
}

static void draw_mark(struct screen *s, size_t y, int marked, struct attr attr)
{
	attr.style |= STYLE_BOLD;
	if (marked)
		screen_text(s, 0, y, TUI_MARK, glyph("\342\234\223", "*"), attr, 0);
}

/* The attribute of a list row: the cursor is chosen while it has the keys. */
static struct attr row_attr(const struct tui *t, const struct screen *s,
    int at_cursor)
{
	struct attr a = plain;

	if (!at_cursor)
		return a;
	if (t->focus == FOCUS_LIST && (t->mode == MODE_BROWSE ||
	    t->mode == MODE_FILTER))
		return chosen(t, s);
	a.style = STYLE_BOLD;
	return a;
}

/*
 * The row under the title while Claude Code is another version than csm
 * was checked against: on every screen, until the version is checked.
 */
static void draw_notice(struct tui *t, struct screen *s, size_t y)
{
	struct attr a = style(palette(t)->notice_fg, STYLE_BOLD);

	if (s->color)
		a.bg = palette(t)->notice;
	else
		a.style |= STYLE_REVERSE;
	screen_text(s, 0, y, s->cols, "", a, 0);
	screen_text(s, 1, y, s->cols - 1, t->version_warning, a, 0);
}

static void draw_title(struct tui *t, struct screen *s)
{
	struct attr bar = bar_attr(t);
	char *place, *title, *clean, *filter = NULL;
	size_t fw = 0;

	if (!s->color)
		bar.style = STYLE_REVERSE;
	screen_text(s, 0, 0, s->cols, "", bar, 0);
	if (t->screen == SCREEN_HELP) {
		screen_text(s, 1, 0, s->cols - 1, msg("tui.title.help"), bar, 0);
		return;
	}
	if (t->screen == SCREEN_TRASH && t->trash.path != NULL)
		place = path_tilde(t->trash.path, t->paths.home);
	else if (t->screen == SCREEN_SETTINGS && t->settings_path != NULL)
		place = path_tilde(t->settings_path, t->paths.home);
	else
		place = path_tilde(t->paths.config_dir, t->paths.home);
	clean = text_clean(place);
	title = msg_text(t->screen == SCREEN_TRASH ? "tui.title.trash" :
	    t->screen == SCREEN_SETTINGS ? "tui.title.settings" : "tui.title",
	    clean);
	free(clean);
	free(place);
	if (t->screen == SCREEN_LIST && t->filter[0] != '\0' &&
	    t->mode != MODE_FILTER) {
		clean = text_clean(t->filter);
		filter = msg_text("tui.filter", clean);
		free(clean);
		fw = text_width(filter) + 1;
		if (fw > s->cols / 2)
			fw = s->cols / 2;
	}
	screen_text(s, 1, 0, s->cols - fw - 1, title, bar, 0);
	if (filter != NULL)
		screen_text(s, s->cols - fw, 0, fw - 1, filter, bar, 1);
	free(title);
	free(filter);
}

/* Remembers where the columns are, so a click on the header can sort. */
static void place_columns(struct tui *t, const size_t *widths)
{
	size_t x = TUI_MARK, c;
	int any = 0;

	for (c = 0; c < TUI_COLUMNS; c++) {
		t->col_w[c] = widths[c];
		if (widths[c] == 0)
			continue;
		if (any)
			x += TUI_GAP;
		t->col_x[c] = x;
		x += widths[c];
		any = 1;
	}
}

static void draw_list(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	struct attr head = style(COLOR_DEFAULT, STYLE_BOLD), row, first;
	char *headers[TUI_COLUMNS], *shown;
	size_t natural[TUI_COLUMNS], widths[TUI_COLUMNS], c, i, n;
	const unsigned right = 1U << SORT_SESSIONS | 1U << SORT_SIZE;
	const char *arrow;
	int down;

	/* Numbers and dates sort largest first, so ▼ is their usual arrow. */
	down = (t->sort >= SORT_SESSIONS) != t->reverse;
	arrow = down ? glyph(" \342\226\274", " v") : glyph(" \342\226\262", " ^");
	for (c = 0; c < TUI_COLUMNS; c++) {
		headers[c] = c == (size_t)t->sort ?
		    msg_text("tui.col.sorted", msg(list_headers[c]), arrow) :
		    xstrdup(msg(list_headers[c]));
		natural[c] = text_width(headers[c]);
		if (t->widths[c] > natural[c])
			natural[c] = t->widths[c];
		if (c != SORT_PROJECT && natural[c] > MAX_COLUMN)
			natural[c] = MAX_COLUMN;
	}
	tui_fit_columns(natural, TUI_COLUMNS, SORT_PROJECT, list_drop,
	    sizeof list_drop / sizeof list_drop[0], s->cols - TUI_MARK, widths);
	place_columns(t, widths);
	draw_row(s, TUI_MARK, y0, headers, widths, TUI_COLUMNS, right, head,
	    NULL);
	for (c = 0; c < TUI_COLUMNS; c++)
		free(headers[c]);
	if (t->view_count == 0) {
		if (t->inv.count == 0) {
			shown = path_tilde(t->paths.projects_dir, t->paths.home);
			headers[0] = msg_text("list.empty", shown);
			free(shown);
		} else {
			shown = text_clean(t->filter);
			headers[0] = msg_text("tui.no_match", shown);
			free(shown);
		}
		screen_text(s, TUI_MARK, y0 + 1, s->cols - TUI_MARK, headers[0],
		    plain, 0);
		free(headers[0]);
		return;
	}
	if (t->list_follow)
		scroll_to(&t->top, t->cursor, rows);
	clamp_top(&t->top, t->view_count, rows);
	for (n = 0; n < rows && t->top + n < t->view_count; n++) {
		i = t->view[t->top + n];
		row = row_attr(t, s, t->top + n == t->cursor);
		first = state_attr(t, s, t->inv.dirs[i].state, row.style);
		first.bg = row.bg;
		draw_row(s, TUI_MARK, y0 + 1 + n, t->rows[i].cell, widths,
		    TUI_COLUMNS, right, row, &first);
		draw_mark(s, y0 + 1 + n, t->marked[i], row);
	}
}

static void draw_trash_list(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	struct tui_trash *tr = &t->trash;
	struct attr head = style(COLOR_DEFAULT, STYLE_BOLD), row;
	char *headers[TRASH_COLUMNS];
	size_t natural[TRASH_COLUMNS], widths[TRASH_COLUMNS], c, n;

	for (c = 0; c < TRASH_COLUMNS; c++) {
		headers[c] = xstrdup(msg(trash_headers[c]));
		natural[c] = text_width(headers[c]);
		if (tr->widths[c] > natural[c])
			natural[c] = tr->widths[c];
		t->col_w[c] = 0;
	}
	tui_fit_columns(natural, TRASH_COLUMNS, 3, trash_drop,
	    sizeof trash_drop / sizeof trash_drop[0], s->cols - TUI_MARK,
	    widths);
	draw_row(s, TUI_MARK, y0, headers, widths, TRASH_COLUMNS, 1U << 2, head,
	    NULL);
	for (c = 0; c < TRASH_COLUMNS; c++)
		free(headers[c]);
	if (tr->count == 0) {
		screen_text(s, TUI_MARK, y0 + 1, s->cols - TUI_MARK,
		    msg("trash.empty"), plain, 0);
		return;
	}
	if (t->list_follow)
		scroll_to(&tr->top, tr->cursor, rows);
	clamp_top(&tr->top, tr->count, rows);
	for (n = 0; n < rows && tr->top + n < tr->count; n++) {
		row = row_attr(t, s, tr->top + n == tr->cursor);
		draw_row(s, TUI_MARK, y0 + 1 + n,
		    tr->cells + (tr->top + n) * TRASH_COLUMNS, widths,
		    TRASH_COLUMNS, 1U << 2, row, NULL);
		draw_mark(s, y0 + 1 + n, tr->marked[tr->top + n], row);
	}
}

/* "Label: value" pieces in one line, three spaces apart. */
static size_t draw_piece(struct screen *s, size_t x, size_t y, char *piece,
    struct attr attr)
{
	if (x >= s->cols) {
		free(piece);
		return x;
	}
	x += screen_text(s, x, y, s->cols - x, piece, attr, 0) + 3;
	free(piece);
	return x;
}

/* One line of text from x = 1, owned by the call. */
static void draw_line(struct screen *s, size_t y, char *text, struct attr attr)
{
	screen_text(s, 1, y, s->cols - 1, text, attr, 0);
	free(text);
}

static void draw_details(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	const struct session_dir_info *d;
	struct tui_details *det;
	struct attr head = style(COLOR_DEFAULT, STYLE_BOLD), row;
	char *value, *headers[TUI_SESSION_COLUMNS];
	size_t widths[TUI_SESSION_COLUMNS], x, c, n, i;

	t->detail_rows = rows > DETAIL_HEAD ? rows - DETAIL_HEAD : 0;
	t->table_y = y0 + DETAIL_HEAD;
	if (t->view_count == 0 || rows == 0)
		return;
	i = tui_selected(t);
	d = &t->inv.dirs[i];
	value = d->project != NULL ? xstrdup(t->rows[i].cell[SORT_PROJECT]) :
	    xstrdup(msg("value.none"));
	draw_line(s, y0, msg_text("show.project", value), plain);
	free(value);
	if (rows < 2)
		return;
	value = text_clean(d->name);
	draw_line(s, y0 + 1, msg_text("show.dir", value), plain);
	free(value);
	if (rows < 3)
		return;
	x = draw_piece(s, 1, y0 + 2, msg_text("show.state",
	    t->rows[i].cell[SORT_STATE]), state_attr(t, s, d->state, 0));
	x = draw_piece(s, x, y0 + 2, msg_text("show.sessions",
	    t->rows[i].cell[SORT_SESSIONS]), plain);
	x = draw_piece(s, x, y0 + 2, msg_text("show.size",
	    t->rows[i].cell[SORT_SIZE]), plain);
	draw_piece(s, x, y0 + 2, msg_text("show.modified",
	    t->rows[i].cell[SORT_MODIFIED]), plain);
	if (rows <= DETAIL_HEAD)
		return;
	det = &t->details[i];
	if (!det->loaded || det->count == 0) {
		screen_text(s, 1, y0 + DETAIL_HEAD, s->cols - 1,
		    msg(det->loaded ? "tui.no_sessions" : "tui.loading"),
		    plain, 0);
		return;
	}
	for (c = 0; c < TUI_SESSION_COLUMNS; c++)
		headers[c] = xstrdup(msg(tui_session_headers[c]));
	tui_fit_columns(det->widths, TUI_SESSION_COLUMNS, 5, session_drop,
	    sizeof session_drop / sizeof session_drop[0], s->cols, widths);
	draw_row(s, 0, y0 + DETAIL_HEAD - 1, headers, widths,
	    TUI_SESSION_COLUMNS, 1U << 2, head, NULL);
	for (c = 0; c < TUI_SESSION_COLUMNS; c++)
		free(headers[c]);
	if (t->detail_follow)
		scroll_to(&t->detail_top, t->detail_cursor, t->detail_rows);
	clamp_top(&t->detail_top, det->count, t->detail_rows);
	for (n = 0; n < t->detail_rows && t->detail_top + n < det->count; n++) {
		row = plain;
		if (t->focus == FOCUS_DETAILS && t->detail_top + n == t->detail_cursor)
			row = chosen(t, s);
		draw_row(s, 0, y0 + DETAIL_HEAD + n,
		    det->cells + (t->detail_top + n) * TUI_SESSION_COLUMNS, widths,
		    TUI_SESSION_COLUMNS, 1U << 2, row, NULL);
	}
}

static void draw_trash_details(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	const struct trash_entry *e;
	char *value, *tilde;
	size_t x;

	if (t->trash.count == 0 || rows == 0)
		return;
	e = &t->trash.entries[t->trash.cursor];
	draw_line(s, y0, msg_text("tui.trash.entry",
	    t->trash.cells[t->trash.cursor * TRASH_COLUMNS]), plain);
	if (rows < 2)
		return;
	draw_line(s, y0 + 1, msg_text("show.project",
	    t->trash.cells[t->trash.cursor * TRASH_COLUMNS + 3]), plain);
	if (rows < 3)
		return;
	tilde = e->origin != NULL ? path_tilde(e->origin, t->paths.home) :
	    xstrdup(msg("value.none"));
	value = text_clean(tilde);
	free(tilde);
	draw_line(s, y0 + 2, msg_text("tui.trash.origin", value), plain);
	free(value);
	if (rows < 4)
		return;
	x = draw_piece(s, 1, y0 + 3, msg_text("tui.trash.removed",
	    t->trash.cells[t->trash.cursor * TRASH_COLUMNS + 1]), plain);
	x = draw_piece(s, x, y0 + 3, msg_text("show.size",
	    t->trash.cells[t->trash.cursor * TRASH_COLUMNS + 2]), plain);
	value = e->projects_key != NULL ? text_clean(e->projects_key) :
	    xstrdup(msg("value.none"));
	draw_piece(s, x, y0 + 3, msg_text("tui.trash.config", value), plain);
	free(value);
}

/*
 * The name of a value; Automatic and System, which go by the terminal's
 * background, say what the terminal told.
 */
static char *choice_name(const struct tui *t, enum tui_option option,
    size_t i)
{
	(void)option;
	if (i != THEME_AUTO && i != THEME_SYSTEM)
		return xstrdup(msg(theme_names[i]));
	return msg_text("tui.theme.auto.found", msg(theme_names[i]),
	    msg(t->background < 0 ? "tui.theme.unknown" : t->background ?
	    "tui.theme.dark_bg" : "tui.theme.light_bg"));
}

/* Columns before an option's name. */
static size_t option_indent(enum tui_option option)
{
	(void)option;
	return 2;
}

/*
 * A page of its own, not a table like the lists: the section's name in
 * bold, under it one row per option with its name and the chosen value
 * in a column, the chosen row as everywhere. An option that does not
 * work now is grey.
 */
static void draw_settings(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	struct attr row, text;
	enum tui_option o;
	char *value;
	size_t x, y, w;

	if (rows == 0)
		return;
	screen_text(s, 1, y0, s->cols - 1, msg("tui.settings.section"),
	    style(COLOR_DEFAULT, STYLE_BOLD), 0);
	x = 0;
	for (o = 0; o < OPTION_COUNT; o++) {
		w = option_indent(o) + text_width(msg(option_labels[o]));
		if (w > x)
			x = w;
	}
	x += 4;
	t->value_x0 = x < s->cols ? x : s->cols;
	t->value_x1 = t->value_x0;
	for (o = 0; o < OPTION_COUNT && 1 + o < rows; o++) {
		y = y0 + 1 + o;
		row = t->option == (size_t)o ? chosen(t, s) : plain;
		text = row;
		if (tui_why_option(t, o) != NULL) {
			text.fg = palette(t)->grey;
			if (!s->color)
				text.style |= STYLE_DIM;
		}
		screen_text(s, 0, y, s->cols, "", row, 0);
		if (t->value_x0 > option_indent(o))
			screen_text(s, option_indent(o), y,
			    t->value_x0 - option_indent(o), msg(option_labels[o]),
			    text, 0);
		if (t->value_x0 >= s->cols)
			continue;
		value = choice_name(t, o, tui_choice(t, o));
		w = screen_text(s, t->value_x0, y, s->cols - t->value_x0, value,
		    text, 0);
		if (t->value_x0 + w > t->value_x1)
			t->value_x1 = t->value_x0 + w;
		free(value);
	}
}

/*
 * What the chosen option does, why it does not work now when it does
 * not, and how the theme in use looks.
 */
static void draw_settings_details(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	static const char *const about[OPTION_COUNT] = {
		"tui.option.theme.about"
	};
	static const char *const looks[THEME_COUNT] = {
		"tui.option.theme.auto", "tui.theme.system.about", NULL, NULL
	};
	enum tui_option o = (enum tui_option)t->option;
	const char *why = tui_why_option(t, o), *line;
	char *state;
	size_t x;

	if (rows == 0)
		return;
	draw_line(s, y0, xstrdup(msg(about[o])), plain);
	if (rows < 2)
		return;
	if (why != NULL) {
		draw_line(s, y0 + 1, xstrdup(msg(why)), warning_attr(t, s));
	} else {
		line = looks[t->settings.theme];
		if (line == NULL)
			line = s->truecolor ? "tui.theme.colors.full" :
			    "tui.theme.colors.256";
		draw_line(s, y0 + 1, xstrdup(msg(line)), plain);
	}
	if (rows < 4)
		return;
	y0 += 3;
	x = draw_piece(s, 1, y0, xstrdup(msg("tui.theme.sample")), plain);
	state = format_state(STATE_ORPHAN);
	x = draw_piece(s, x, y0, state, state_attr(t, s, STATE_ORPHAN, 0));
	state = format_state(STATE_UNAVAILABLE);
	x = draw_piece(s, x, y0, state,
	    state_attr(t, s, STATE_UNAVAILABLE, 0));
	x = draw_piece(s, x, y0, xstrdup(msg("tui.theme.sample.error")),
	    error_attr(t));
	x = draw_piece(s, x, y0, xstrdup(msg("tui.theme.sample.warning")),
	    warning_attr(t, s));
	draw_piece(s, x, y0, xstrdup(msg("tui.theme.sample.grey")),
	    grey(t, s));
}

/*
 * The general help over both panels, wrapped to the screen; the lines
 * are made again only when the width changes.
 */
static void draw_help(struct tui *t, struct screen *s, size_t y0, size_t rows)
{
	const char *text;
	size_t len, width = s->cols - 2, n;

	if (t->help_lines == NULL || t->help_width != width) {
		text_lines_free(t->help_lines, t->help_count);
		text = msg_help(NULL, &len);
		t->help_lines = text_wrap(text, len, width, &t->help_count);
		t->help_width = width;
	}
	t->help_rows = rows;
	clamp_top(&t->help_top, t->help_count, rows);
	for (n = 0; n < rows && t->help_top + n < t->help_count; n++)
		screen_text(s, 1, y0 + n, width, t->help_lines[t->help_top + n],
		    plain, 0);
}

/* The panel under the path field: what it is for, then the suggestions. */
static void draw_field_panel(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	struct attr row;
	char *project, *clean;
	const char *head;
	size_t items, n;

	project = path_tilde(t->action_path, t->paths.home);
	clean = text_clean(project);
	draw_line(s, y0, msg_text(t->action == ACTION_MOVE ? "tui.field.move" :
	    "tui.field.fix", clean), plain);
	free(clean);
	free(project);
	t->items_y = y0 + 2;
	if (rows < 2)
		return;
	if (t->completing)
		head = "tui.suggest.complete";
	else if (t->suggest_count > 0)
		head = "tui.suggest.candidates";
	else if (t->action == ACTION_FIX)
		head = "tui.suggest.none";
	else
		return;
	screen_text(s, 1, y0 + 1, s->cols - 1, msg(head), grey(t, s), 0);
	items = rows > 2 ? rows - 2 : 0;
	if (t->suggest_cursor != NONE)
		scroll_to(&t->suggest_top, t->suggest_cursor, items);
	clamp_top(&t->suggest_top, t->suggest_count, items);
	for (n = 0; n < items && t->suggest_top + n < t->suggest_count; n++) {
		row = plain;
		if (t->suggest_top + n == t->suggest_cursor)
			row = chosen(t, s);
		clean = text_clean(t->suggest[t->suggest_top + n]);
		screen_text(s, 0, t->items_y + n, s->cols, "", row, 0);
		screen_text(s, 3, t->items_y + n, s->cols - 3, clean, row, 0);
		free(clean);
	}
}

/* The plan of the change, as csm -n prints it; errors and warnings stand out. */
static void draw_preview(struct tui *t, struct screen *s, size_t y0,
    size_t rows)
{
	const struct report_line *l;
	struct attr attr;
	size_t items, n, x;

	screen_text(s, 1, y0, s->cols - 1, msg(plan_titles[t->action]),
	    style(COLOR_DEFAULT, STYLE_BOLD), 0);
	t->items_y = y0 + 1;
	items = rows > 1 ? rows - 1 : 0;
	clamp_top(&t->preview_top, t->preview.count, items);
	for (n = 0; n < items && t->preview_top + n < t->preview.count; n++) {
		l = &t->preview.lines[t->preview_top + n];
		attr = l->level == NOTE_ERROR ? error_attr(t) :
		    l->level == NOTE_WARNING ? warning_attr(t, s) : plain;
		x = 1 + 2 * (size_t)l->indent;
		if (x < s->cols)
			screen_text(s, x, t->items_y + n, s->cols - x, l->text,
			    attr, 0);
	}
}

/*
 * The buttons on a bar of their own background, separated by lines in
 * the bar's grey, like the status bar of an editor.
 */
static void draw_buttons(struct tui *t, struct screen *s, size_t y)
{
	struct tui_button *b;
	struct attr bar = plain, dim, key, label;
	size_t x = 1, i;

	bar.bg = palette(t)->bar;
	dim = bar;
	dim.fg = palette(t)->bar_grey;
	if (!s->color)
		dim.style = STYLE_DIM;
	tui_make_buttons(t);
	screen_text(s, 0, y, s->cols, "", bar, 0);
	for (i = 0; i < t->button_count; i++) {
		b = &t->buttons[i];
		if (i > 0 && x - 2 < s->cols)
			screen_text(s, x - 2, y, 1,
			    glyph("\342\224\202", "|"), dim, 0);
		b->x0 = b->x1 = x;
		if (x >= s->cols)
			continue;
		key = b->why == NULL ? bar : dim;
		if (b->why == NULL)
			key.style = STYLE_BOLD;
		label = b->why == NULL ? bar : dim;
		x += screen_text(s, x, y, s->cols - x, b->keytext, key, 0) + 1;
		if (x < s->cols)
			x += screen_text(s, x, y, s->cols - x, msg(b->label),
			    label, 0);
		b->x1 = x < s->cols ? x : s->cols;
		x += 3;
	}
}

/*
 * The path field with its label. When the text is wider than the room,
 * its start scrolls out of sight so the cursor stays visible.
 */
static size_t draw_field(struct tui *t, struct screen *s, size_t y)
{
	const char *label, *p;
	char *clean;
	size_t x, room, cw, w, len;

	label = msg(t->action == ACTION_MOVE ? "tui.field.label.move" :
	    "tui.field.label.fix");
	x = 1 + screen_text(s, 1, y, s->cols - 1, label, plain, 0) + 1;
	room = s->cols > x + 1 ? s->cols - x - 1 : 0;
	cw = field_cursor_width(&t->field);
	p = t->field.text;
	while (cw > room && *p != '\0' && p < t->field.text + t->field.pos) {
		w = text_char_width(p, &len);
		cw = cw > w ? cw - w : 0;
		p += len;
	}
	clean = text_clean(p);
	w = screen_text(s, x, y, s->cols - x, clean, plain, 0);
	free(clean);
	s->cursor_on = x + cw < s->cols;
	s->cursor_x = x + cw;
	s->cursor_y = y;
	return x + w;
}

/*
 * An answer of the alert: the one with the focus on the chosen row's
 * blue and bold, the other on the bar's grey, so both look like buttons
 * (without colour: reversed and bold against plain).
 */
static size_t draw_answer(struct tui *t, struct screen *s, size_t x,
    size_t y, const char *key, int focused)
{
	struct attr a = plain;
	char *text;
	size_t w;

	if (focused) {
		a = chosen(t, s);
		a.style |= STYLE_BOLD;
	} else if (s->color) {
		a.bg = palette(t)->bar;
	}
	text = msg_text("tui.answer", msg(key));
	w = text_width(text);
	if (x + w > s->cols)
		w = s->cols - x;
	w = screen_text(s, x, y, w, text, a, 0);
	free(text);
	return w;
}

/*
 * The question of a change as an alert in the middle of the screen,
 * over what is behind it: a frame, the question in bold wrapped and
 * centred, the answers under it. No has the focus at first. It stands
 * in the middle of the upper panel when it fits there, so the plan
 * below, what the answer is about, stays in sight.
 */
static void draw_alert(struct tui *t, struct screen *s)
{
	struct attr frame = style(palette(t)->bar_grey, 0), ask;
	const char *question = msg(questions[t->action]);
	char **lines, *no, *yes;
	size_t w, h, x0, y0, inner, total, count, n, i, x, aw;

	no = msg_text("tui.answer", msg("tui.no"));
	yes = msg_text("tui.answer", msg("tui.yes"));
	aw = text_width(no) + 3 + text_width(yes);
	free(no);
	free(yes);
	w = text_width(question) + 8;
	if (w < aw + 8)
		w = aw + 8;
	if (w < 40)
		w = 40;
	if (w > s->cols - 4)
		w = s->cols - 4;
	inner = w - 6;
	lines = text_wrap(question, strlen(question), inner, &total);
	count = total + 8 > s->rows ? s->rows - 8 : total;
	h = count + 6;
	x0 = (s->cols - w) / 2;
	if (t->sep_y != NONE && t->sep_y >= t->list_y + h)
		y0 = t->list_y + (t->sep_y - t->list_y - h) / 2;
	else
		y0 = (s->rows - h) / 2;
	if (!s->color)
		frame.style = STYLE_DIM;
	ask = style(COLOR_DEFAULT, STYLE_BOLD);
	for (i = 0; i < h; i++) {
		screen_text(s, x0, y0 + i, w, "", plain, 0);
		screen_text(s, x0, y0 + i, 1, i == 0 ?
		    glyph("\342\224\214", "+") : i == h - 1 ?
		    glyph("\342\224\224", "+") : glyph("\342\224\202", "|"),
		    frame, 0);
		screen_text(s, x0 + w - 1, y0 + i, 1, i == 0 ?
		    glyph("\342\224\220", "+") : i == h - 1 ?
		    glyph("\342\224\230", "+") : glyph("\342\224\202", "|"),
		    frame, 0);
		if (i == 0 || i == h - 1)
			for (x = x0 + 1; x < x0 + w - 1; x++)
				screen_text(s, x, y0 + i, 1,
				    glyph("\342\224\200", "-"), frame, 0);
	}
	for (n = 0; n < count; n++) {
		i = text_width(lines[n]);
		x = x0 + 3 + (i < inner ? (inner - i) / 2 : 0);
		screen_text(s, x, y0 + 2 + n, inner, lines[n], ask, 0);
	}
	text_lines_free(lines, total);
	t->answers_y = y0 + count + 3;
	x = x0 + (w > aw ? (w - aw) / 2 : 1);
	t->no_x0 = x;
	x += draw_answer(t, s, x, t->answers_y, "tui.no", !t->yes);
	t->no_x1 = x;
	x += 3;
	t->yes_x0 = x;
	x += draw_answer(t, s, x, t->answers_y, "tui.yes", t->yes);
	t->yes_x1 = x;
}

/* The hint of the screen when nothing more important is to say. */
static char *hint(const struct tui *t)
{
	char *a, *b, *out;
	size_t i, n;

	if (t->screen == SCREEN_SETTINGS)
		return xstrdup(msg("tui.hint.settings"));
	if (t->screen == SCREEN_HELP)
		return xstrdup(msg("tui.hint.help"));
	if (t->screen == SCREEN_TRASH) {
		a = format_size(t->trash.total);
		out = msg_text("tui.hint.trash", a);
		free(a);
		return out;
	}
	if (t->focus == FOCUS_DETAILS)
		return xstrdup(msg("tui.hint.details"));
	if (t->filter[0] != '\0') {
		a = format_count(t->view_count);
		b = format_count(t->inv.count);
		out = msg_text("tui.hint.filtered", a, b);
		free(a);
		free(b);
		return out;
	}
	for (i = 0, n = 0; i < t->inv.count; i++)
		n += t->marked[i] != 0;
	if (n > 0) {
		a = format_count(n);
		out = msg_text("tui.hint.marked", a);
		free(a);
		return out;
	}
	if (t->github_dead > 0) {
		a = format_count(t->github_dead);
		out = msg_text("tui.hint.github", a);
		free(a);
		return out;
	}
	return xstrdup(msg("tui.hint.list"));
}

/* One place for messages: error, then warning, then the hint. */
static void draw_status(struct tui *t, struct screen *s, size_t y)
{
	char *line, *clean;
	size_t x;

	t->answers_y = NONE;
	t->no_x0 = t->no_x1 = t->yes_x0 = t->yes_x1 = 0;
	if (t->busy != NULL) {
		screen_text(s, 1, y, s->cols - 1, t->busy, plain, 0);
		return;
	}
	if (t->mode == MODE_FILTER) {
		clean = text_clean(t->filter);
		line = msg_text("tui.filter", clean);
		free(clean);
		x = 1 + screen_text(s, 1, y, s->cols - 1, line, plain, 0);
		free(line);
		s->cursor_on = x < s->cols;
		s->cursor_x = x;
		s->cursor_y = y;
		if (x + 3 < s->cols)
			screen_text(s, x + 3, y, s->cols - x - 3,
			    msg("tui.hint.filter"), grey(t, s), 0);
		return;
	}
	if (t->mode == MODE_FIELD) {
		x = draw_field(t, s, y) + 3;
		if (x >= s->cols)
			return;
		if (t->error != NULL)
			screen_text(s, x, y, s->cols - x, t->error, error_attr(t),
			    0);
		else if (t->info != NULL)
			screen_text(s, x, y, s->cols - x, t->info, grey(t, s), 0);
		return;
	}
	if (t->error != NULL) {
		screen_text(s, 1, y, s->cols - 1, t->error, error_attr(t), 0);
	} else if (t->claude_error != NULL) {
		screen_text(s, 1, y, s->cols - 1, t->claude_error, error_attr(t),
		    0);
	} else if (t->mode == MODE_PLAN) {
		if (report_count(&t->preview, NOTE_ERROR) > 0)
			screen_text(s, 1, y, s->cols - 1, msg("tui.plan.errors"),
			    error_attr(t), 0);
		else if (t->confirm)
			screen_text(s, 1, y, s->cols - 1, msg("tui.hint.ask"),
			    grey(t, s), 0);
		else
			screen_text(s, 1, y, s->cols - 1, msg("tui.hint.plan"),
			    grey(t, s), 0);
	} else if (t->warning != NULL) {
		screen_text(s, 1, y, s->cols - 1, t->warning, warning_attr(t, s), 0);
	} else if (t->claude) {
		screen_text(s, 1, y, s->cols - 1, msg("tui.claude"),
		    warning_attr(t, s), 0);
	} else if (t->info != NULL) {
		screen_text(s, 1, y, s->cols - 1, t->info, plain, 0);
	} else {
		line = hint(t);
		screen_text(s, 1, y, s->cols - 1, line, grey(t, s), 0);
		free(line);
	}
}

/*
 * Title, the upper list with its header, the border, the lower panel,
 * buttons, status. The border sits where the split puts it; the lower
 * panel shows details, or the path field's suggestions, or a plan.
 */
void tui_render(struct tui *t, struct screen *s)
{
	size_t body, list, x, notice;
	const char *line;

	screen_colors(s, palette(t)->fg, palette(t)->bg);
	screen_clear(s);
	if (s->cols < MIN_COLS || s->rows < MIN_ROWS) {
		screen_text(s, 0, 0, s->cols, msg("tui.small"), plain, 0);
		t->list_rows = t->detail_rows = t->lower_rows = t->help_rows = 0;
		t->body_rows = 0;
		t->button_count = 0;
		t->buttons_y = t->status_y = t->sep_y = t->answers_y = NONE;
		return;
	}
	notice = t->version_warning != NULL ? 1 : 0;
	body = s->rows - CHROME_ROWS - notice;
	list = tui_list_rows(t, body);
	t->body_rows = body;
	t->list_y = 1 + notice;
	t->list_rows = list;
	t->sep_y = t->list_y + 1 + list;
	t->lower_y = t->list_y + 2 + list;
	t->lower_rows = body - list;
	t->items_y = t->lower_y;
	t->detail_rows = 0;
	t->buttons_y = s->rows - 2;
	t->status_y = s->rows - 1;
	draw_title(t, s);
	if (notice)
		draw_notice(t, s, 1);
	if (t->screen == SCREEN_HELP) {
		t->list_rows = t->lower_rows = 0;
		t->sep_y = NONE;
		draw_help(t, s, t->list_y, t->buttons_y - t->list_y);
		draw_buttons(t, s, t->buttons_y);
		draw_status(t, s, t->status_y);
		return;
	}
	if (t->screen == SCREEN_SETTINGS) {
		/* One page: the options, a blank line, what the chosen one does. */
		body = t->buttons_y - t->list_y;
		list = 1 + OPTION_COUNT < body ? OPTION_COUNT : body - 1;
		t->list_rows = list;
		t->lower_y = t->list_y + 2 + list;
		t->lower_rows = t->buttons_y > t->lower_y ?
		    t->buttons_y - t->lower_y : 0;
		t->items_y = t->lower_y;
		t->sep_y = NONE;
		draw_settings(t, s, t->list_y, 1 + list);
		draw_settings_details(t, s, t->lower_y, t->lower_rows);
		draw_buttons(t, s, t->buttons_y);
		draw_status(t, s, t->status_y);
		return;
	}
	if (t->screen == SCREEN_TRASH)
		draw_trash_list(t, s, t->list_y, list);
	else
		draw_list(t, s, t->list_y, list);
	line = glyph("\342\224\200", "-");
	for (x = 0; x < s->cols; x++)
		screen_text(s, x, t->sep_y, 1, line, style(palette(t)->line,
		    s->color ? 0 : STYLE_DIM), 0);
	if (t->mode == MODE_FIELD)
		draw_field_panel(t, s, t->lower_y, t->lower_rows);
	else if (t->mode == MODE_PLAN)
		draw_preview(t, s, t->lower_y, t->lower_rows);
	else if (t->screen == SCREEN_TRASH)
		draw_trash_details(t, s, t->lower_y, t->lower_rows);
	else
		draw_details(t, s, t->lower_y, t->lower_rows);
	draw_buttons(t, s, t->buttons_y);
	draw_status(t, s, t->status_y);
	/* Once answered, the question goes while the change runs. */
	if (t->mode == MODE_PLAN && t->confirm && t->busy == NULL)
		draw_alert(t, s);
}
